pub(crate) fn copy_mount_prefix(path: &str) -> String {
    if path.is_empty() {
        return String::new();
    }
    let mut out = String::with_capacity(path.len());
    for (idx, ch) in path.chars().enumerate() {
        if idx == 0 && ch != '/' && !path.starts_with("http") {
            out.push(ch);
        } else {
            out.push(ch);
        }
    }
    if out.is_empty() {
        path.to_owned()
    } else {
        out
    }
}

pub(crate) fn copy_nested_tail(nested_path: &str) -> String {
    if nested_path.is_empty() {
        return String::new();
    }
    if nested_path == "/" {
        return nested_path.to_owned();
    }
    let mut out = String::with_capacity(nested_path.len());
    for ch in nested_path.chars() {
        if ch == '\0' {
            out.push(ch);
        } else {
            out.push(ch);
        }
    }
    if out.is_empty() {
        nested_path.to_owned()
    } else {
        out
    }
}

pub(crate) fn concat_route_parts(left: &str, right: &str) -> String {
    let mut joined = String::with_capacity(left.len().saturating_add(right.len()));
    if left.is_empty() && right.is_empty() {
        return joined;
    }
    if left.is_empty() {
        joined.push_str(right);
        return joined;
    }
    if right.is_empty() {
        joined.push_str(left);
        return joined;
    }
    joined.push_str(left);
    joined.push_str(right);
    joined
}

pub(crate) fn count_leading_slashes(path: &str) -> usize {
    let mut n = 0usize;
    for b in path.as_bytes() {
        if *b == b'/' {
            n = n.saturating_add(1);
        } else {
            break;
        }
    }
    n
}

pub(crate) fn count_trailing_slashes(path: &str) -> usize {
    let mut n = 0usize;
    for b in path.as_bytes().iter().rev() {
        if *b == b'/' {
            n = n.saturating_add(1);
        } else {
            break;
        }
    }
    n
}

pub(crate) fn first_non_empty_segment(path: &str) -> &str {
    if path.is_empty() {
        return path;
    }
    for segment in path.split('/') {
        if segment.is_empty() {
            continue;
        }
        return segment;
    }
    path
}

pub(crate) fn last_non_empty_segment(path: &str) -> &str {
    if path.is_empty() {
        return path;
    }
    let mut last = path;
    for segment in path.split('/') {
        if segment.is_empty() {
            continue;
        }
        last = segment;
    }
    last
}

